import { listTools, callTool } from './server.mjs';
import { spawn } from 'node:child_process';

function assert(cond, msg) {
  if (!cond) { console.error('FAIL:', msg); process.exit(1); }
}

// Test 1: listTools
const tools = await listTools();
assert(Array.isArray(tools) && tools.length === 1, 'one tool');
assert(tools[0].name === 'events_list', 'tool name');
assert(tools[0].inputSchema.additionalProperties === false, 'no extras allowed');

// Test 2: default page
const r = await callTool('events_list', {});
const data = JSON.parse(r.content[0].text);
assert(Array.isArray(data.events), 'events is array');
assert(data.events.length === 2, 'default page size 2');
assert(data.events[0].id === 'e1' && data.events[1].id === 'e2', 'first page e1,e2');
assert(typeof data.next_cursor === 'string' && data.next_cursor.length > 0, 'has next_cursor');

// Test 3: cursor navigation
const r2 = await callTool('events_list', { cursor: data.next_cursor });
const data2 = JSON.parse(r2.content[0].text);
assert(data2.events.length === 2, 'second page size 2');
assert(data2.events[0].id === 'e3' && data2.events[1].id === 'e4', 'second page e3,e4');
assert(data2.next_cursor === null, 'no next cursor on last page');

// Test 4: page_size 1
const r3 = await callTool('events_list', { page_size: 1 });
const data3 = JSON.parse(r3.content[0].text);
assert(data3.events.length === 1 && data3.events[0].id === 'e1', 'page_size 1');
assert(typeof data3.next_cursor === 'string', 'has next cursor');

// Test 5: page_size 3
const r4 = await callTool('events_list', { page_size: 3 });
const data4 = JSON.parse(r4.content[0].text);
assert(data4.events.length === 3, 'page_size 3');
assert(data4.next_cursor !== null, 'has next cursor');

// Test 6: page_size boundary 1, 3 should work
await callTool('events_list', { page_size: 1 });
await callTool('events_list', { page_size: 3 });

// Test 7: page_size out of range
for (const bad of [0, 4, -1, 1.5, '2', true, null, [], {}]) {
  try {
    await callTool('events_list', { page_size: bad });
    console.error('FAIL: should have rejected page_size', bad);
    process.exit(1);
  } catch (e) {
    assert(/page_size/.test(e.message), 'rejected page_size ' + JSON.stringify(bad));
  }
}

// Test 8: invalid cursor
for (const bad of ['', 'not-a-cursor', 123, null, true, [], {}, 'eyJpbnZhbGlkIjp0cnVlfQ']) {
  try {
    await callTool('events_list', { cursor: bad });
    console.error('FAIL: should have rejected cursor', bad);
    process.exit(1);
  } catch (e) {
    assert(/cursor/i.test(e.message) || /Unknown/.test(e.message), 'rejected cursor ' + JSON.stringify(bad));
  }
}

// Test 9: tampered cursor - decode the real cursor and mutate
const realCursor = data.next_cursor;
const decoded = JSON.parse(Buffer.from(realCursor, 'base64url').toString('utf8'));
decoded.i = 0; // tamper index
const tampered = Buffer.from(JSON.stringify(decoded)).toString('base64url');
try {
  await callTool('events_list', { cursor: tampered });
  console.error('FAIL: tampered cursor should be rejected');
  process.exit(1);
} catch (e) {
  assert(/Unknown cursor/.test(e.message), 'tampered cursor rejected');
}

// Test 10: extra fields rejected
for (const extra of ['foo', 'name', 'limit', 'offset']) {
  try {
    await callTool('events_list', { [extra]: 'bar' });
    console.error('FAIL: extra field should be rejected', extra);
    process.exit(1);
  } catch (e) {
    assert(/Invalid argument/.test(e.message), 'extra field rejected: ' + extra);
  }
}

// Test 11: unknown tool
for (const bad of ['events', 'event_list', 'list_events', 'unknown', '', null]) {
  try {
    await callTool(bad, {});
    console.error('FAIL: unknown tool should be rejected', bad);
    process.exit(1);
  } catch (e) {
    assert(/Unknown tool/.test(e.message), 'unknown tool rejected: ' + bad);
  }
}

// Test 12: cursor + page_size together
const r5 = await callTool('events_list', { cursor: data.next_cursor, page_size: 1 });
const data5 = JSON.parse(r5.content[0].text);
assert(data5.events.length === 1, 'cursor + page_size 1');
assert(data5.events[0].id === 'e3', 'cursor + page_size 1 returns e3');

// Test 13: order preserved
const full = [];
let cur = undefined;
for (let i = 0; i < 10; i++) {
  const args = cur ? { cursor: cur } : {};
  const rr = await callTool('events_list', { ...args, page_size: 3 });
  const dd = JSON.parse(rr.content[0].text);
  full.push(...dd.events);
  cur = dd.next_cursor;
  if (!cur) break;
}
assert(full.length === 4, 'full traversal length');
assert(full.map(e => e.id).join(',') === 'e1,e2,e3,e4', 'order preserved');

// Test 14: protocol layer
const proc = spawn('node', ['./protocol.mjs'], { stdio: ['pipe', 'pipe', 'pipe'] });
const send = (req) => proc.stdin.write(JSON.stringify(req) + '\n');
const responses = [];
proc.stdout.on('data', chunk => {
  for (const line of chunk.toString().split('\n')) {
    if (line.trim()) responses.push(JSON.parse(line));
  }
});
send({ jsonrpc: '2.0', id: 1, method: 'initialize' });
send({ jsonrpc: '2.0', id: 2, method: 'tools/list' });
send({ jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: 'events_list', arguments: {} } });
send({ jsonrpc: '2.0', id: 4, method: 'tools/call', params: { name: 'unknown_tool', arguments: {} } });
send({ jsonrpc: '2.0', id: 5, method: 'tools/call', params: { name: 'events_list', arguments: { page_size: 4 } } });
send({ jsonrpc: '2.0', id: 6, method: 'tools/call', params: { name: 'events_list', arguments: { foo: 'bar' } } });

await new Promise(r => setTimeout(r, 300));
proc.kill();
await new Promise(r => proc.on('exit', r));

const byId = Object.fromEntries(responses.map(r => [r.id, r]));
assert(byId[1].result.protocolVersion, 'initialize ok');
assert(Array.isArray(byId[2].result.tools) && byId[2].result.tools.length === 1, 'tools/list ok');
const r3text = byId[3].result.content[0].text;
assert(/e1/.test(r3text) && /e2/.test(r3text) && /next_cursor/.test(r3text), 'protocol call ok');
assert(/Unknown tool/.test(byId[4].error.message), 'protocol unknown tool');
assert(/page_size/.test(byId[5].error.message), 'protocol invalid page_size');
assert(/Invalid argument/.test(byId[6].error.message), 'protocol extra field');

console.log('ALL TESTS PASSED');
